css:
[data-thread-item]{border-radius:6px!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:6px!important;}
[data-slot="button"]{font-weight:500;}
[data-slot="composer-host"]{border-radius:12px!important;border:1px solid var(--border)!important;box-shadow:none!important;}
[data-slot="composer-host"]:focus-within{border-color:color-mix(in srgb,var(--foreground) 40%,transparent)!important;box-shadow:0 0 0 4px color-mix(in srgb,var(--foreground) 8%,transparent)!important;}
[data-user-message-bubble]{border-radius:12px!important;}
.chat-markdown-codeblock{border-radius:6px!important;border:1px solid var(--border);}
[data-slot="dialog-popup"]{border-radius:12px!important;border:1px solid var(--border)!important;}
[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:12px!important;border:1px solid var(--border)!important;box-shadow:0 4px 8px -4px rgba(0,0,0,.04),0 16px 24px -8px rgba(0,0,0,.06)!important;}
[data-slot="tooltip-popup"]{border-radius:6px!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 10%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
.dark [data-slot="switch"][data-unchecked]{background:#2E2E2E!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#EBEBEB!important;box-shadow:inset 0 0 0 1px #C9C9C9!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
.dark [data-slot="switch"][data-checked]{background:#EDEDED!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#0A0A0A!important;}
:root:not(.dark) [data-slot="switch"][data-checked]{background:#171717!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:8px;height:8px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 16%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
::selection{background:color-mix(in srgb,#0070F3 35%,transparent);}
